package ds.seed5482;

import ds.Grafo;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.Test;
import org.junit.experimental.categories.Category;
import org.junit.runner.RunWith;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;

/**
 * Improved test suite for ds.Grafo.
 *
 * These tests are intended to be more descriptive than autogenerated
 * counterparts. Each test follows a simple Given-When-Then structure
 * in comments and includes multiple assertions where appropriate.
 *
 * Requirement reference: REQ-GRAFO-001 (basic graph operations)
 */
interface UnitTest {}

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, useJEE = true)
@Category(UnitTest.class)
public class EvoAITest extends Grafo_ESTest_scaffolding {

    /* Helper: capture output of imprime() to validate printed content without polluting test output. */
    private static String captureImprimeOutput(Grafo g) {
        PrintStream original = System.out;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(baos);
        try {
            System.setOut(ps);
            g.imprime();
        } finally {
            System.out.flush();
            System.setOut(original);
        }
        return baos.toString();
    }

    /* Helper: expect a specific exception from an action; returns the thrown exception. */
    private static <T extends Throwable> T expectThrows(Class<T> expected, Runnable action) {
        try {
            action.run();
        } catch (Throwable t) {
            if (expected.isInstance(t)) {
                @SuppressWarnings("unchecked")
                T cast = (T) t;
                return cast;
            } else {
                String msg = String.format("Unexpected exception type: expected %s but got %s",
                        expected.getName(), t.getClass().getName());
                throw new AssertionError(msg, t);
            }
        }
        throw new AssertionError("Expected exception: " + expected.getName());
    }

    @Test(timeout = 4000)
    public void test0() throws Throwable {
        // Given: graphs of various sizes to exercise boundary behaviour
        final int LARGE = 4389; // boundary-like large size used by original test

        // When: construct a large graph and add edges at boundaries
        Grafo largeG = new Grafo(LARGE);
        // insert a small self-loop and an edge from last to first vertex
        largeG.insereAresta(0, 1, 5);
        largeG.insereAresta(LARGE - 1, 0, 7);

        // Then: grafoTransposto should succeed and reflect reversed edges
        Grafo transposed = largeG.grafoTransposto();
        assertNotNull("Transposed graph should not be null", transposed);
        assertEquals("Transposed graph should maintain vertex count", largeG.numVertices(), transposed.numVertices());
        assertTrue("Transposed should contain edge 1->0 (reverse of 0->1)", transposed.existeAresta(1, 0));
        assertTrue("Transposed should contain edge 0->" + (LARGE - 1) + " (reverse of last->0)",
                transposed.existeAresta(0, LARGE - 1));

        // Also cover empty graph boundary (size 0)
        Grafo empty = new Grafo(0);
        Grafo emptyTransposed = empty.grafoTransposto();
        assertNotNull("Transpose of empty graph should not be null", emptyTransposed);
        assertEquals("Transpose of empty graph should still have 0 vertices", 0, emptyTransposed.numVertices());
    }

    @Test(timeout = 4000)
    public void test1() throws Throwable {
        // Given: a single-vertex graph with a negative-weight self-loop
        Grafo grafo0 = new Grafo(1);
        grafo0.insereAresta(0, 0, -93);

        // When: capture printing output and query properties
        String printed = captureImprimeOutput(grafo0);

        // Then: validate basic graph invariants and that imprime produced some output
        assertEquals("Graph should report one vertex", 1, grafo0.numVertices());
        assertTrue("Self-loop should be reported by existeAresta", grafo0.existeAresta(0, 0));
        assertNotNull("Printed representation should not be null", printed);
        assertTrue("Printed output should contain vertex index '0' or weight '-93'", printed.length() > 0);
        // Also verify retiraAresta returns the expected edge with correct weight
        Grafo.Aresta removed = grafo0.retiraAresta(0, 0);
        assertNotNull("Removed edge should not be null", removed);
        assertEquals("Removed edge v1 should be 0", 0, removed.v1());
        assertEquals("Removed edge v2 should be 0", 0, removed.v2());
        assertEquals("Removed edge weight should match", -93, removed.peso());
        assertFalse("After removal, the edge should no longer exist", grafo0.existeAresta(0, 0));
    }

    @Test(timeout = 4000)
    public void test2() throws Throwable {
        // Given: a large graph and a single inserted self-edge at index 1
        final int SIZE = 4389;
        Grafo grafo0 = new Grafo(SIZE);

        // When: add and then remove an edge
        grafo0.insereAresta(1, 1, 1);
        Grafo.Aresta removed = grafo0.retiraAresta(1, 1);

        // Then: validate returned edge and graph size, and that edge no longer exists
        assertNotNull("retiraAresta should return the removed edge", removed);
        assertEquals("Removed edge source should be 1", 1, removed.v1());
        assertEquals("Removed edge target should be 1", 1, removed.v2());
        assertEquals("Removed edge weight should be 1", 1, removed.peso());
        assertEquals("Graph vertex count should be preserved", SIZE, grafo0.numVertices());
        assertFalse("Edge should no longer exist after removal", grafo0.existeAresta(1, 1));
    }

    @Test(timeout = 4000)
    public void test3() throws Throwable {
        // Given: a graph with a single valid self-edge
        Grafo grafo0 = new Grafo(1);
        grafo0.insereAresta(0, 0, 1);

        // When: attempt to remove a non-existent/out-of-range edge
        Grafo.Aresta nonExistent = grafo0.retiraAresta(0, 4344);

        // Then: retiraAresta should return null for a non-existent edge and original edge remains
        assertNull("Removing a non-existent edge should return null", nonExistent);
        assertTrue("Original self-edge should still exist", grafo0.existeAresta(0, 0));
        assertEquals("Vertex count should remain unchanged", 1, grafo0.numVertices());
    }

    @Test(timeout = 4000)
    public void test4() throws Throwable {
        // Given: a graph and an attempt to insert an edge with an invalid (negative) vertex index
        Grafo grafo0 = new Grafo(1);
        grafo0.insereAresta(0, 0, -93); // valid insertion

        // When/Then: inserting with a negative target index should raise an IndexOutOfBoundsException
        IndexOutOfBoundsException ex = expectThrows(IndexOutOfBoundsException.class, () ->
                grafo0.insereAresta(0, -2922, 3274)
        );
        assertNotNull("Exception message should be present", ex.getMessage());
        // Verify graph remains consistent after failed insertion
        assertTrue("Previously inserted self-edge should still exist", grafo0.existeAresta(0, 0));
    }

    @Test(timeout = 4000)
    public void test5() throws Throwable {
        // Given: a large graph with no edges
        final int SIZE = 4592;
        Grafo grafo0 = new Grafo(SIZE);

        // When: request the first adjacency list for a valid vertex (0)
        // We only assert that the call completes without throwing and that size is correct.
        Object first = null;
        try {
            first = grafo0.primeiroListaAdj(0);
        } catch (IndexOutOfBoundsException e) {
            fail("primeiroListaAdj should accept index 0 for graph with " + SIZE + " vertices");
        }

        // Then: vertex count remains correct and primeiroListaAdj returns either null or a node object
        assertEquals("Graph should report expected number of vertices", SIZE, grafo0.numVertices());
        // first may be null (no adjacency) or non-null (some internal node). Both acceptable.
        // For extra validation, ensure out-of-range index throws.
        expectThrows(IndexOutOfBoundsException.class, () -> grafo0.primeiroListaAdj(SIZE));
    }

    @Test(timeout = 4000)
    public void test6() throws Throwable {
        // Given: a single-vertex graph
        Grafo grafo0 = new Grafo(1);

        // When: insert an edge and check existence
        grafo0.insereAresta(0, 0, 1);
        boolean existsBefore = grafo0.existeAresta(0, 0);

        // Then: edge should be present; after removal it should be absent
        assertTrue("Inserted edge should exist", existsBefore);
        assertEquals("Graph size unchanged after insertion", 1, grafo0.numVertices());
        Grafo.Aresta removed = grafo0.retiraAresta(0, 0);
        assertNotNull("Removal should return the removed edge", removed);
        assertFalse("Edge should no longer exist after removal", grafo0.existeAresta(0, 0));
    }

    @Test(timeout = 4000)
    public void test7() throws Throwable {
        // Given: a single-vertex graph with a self-loop
        Grafo grafo0 = new Grafo(1);
        grafo0.insereAresta(0, 0, 1);

        // When: check for an edge to an out-of-range vertex; handle either boolean false or IndexOutOfBoundsException
        try {
            boolean exists = grafo0.existeAresta(0, 1484);
            assertFalse("Non-existent / out-of-range edge should not be reported as existing", exists);
        } catch (IndexOutOfBoundsException e) {
            // acceptable behavior: implementation may throw for out-of-range vertices
            assertNotNull("IndexOutOfBoundsException message should be informative", e.getMessage());
        }

        // Then: ensure original self-loop still present and graph size correct
        assertTrue("Original self-loop should still exist", grafo0.existeAresta(0, 0));
        assertEquals("Graph should still have one vertex", 1, grafo0.numVertices());
    }

    @Test(timeout = 4000)
    public void test8() throws Throwable {
        // Given: an empty graph (0 vertices)
        Grafo grafo0 = new Grafo(0);

        // Then: numVertices should be zero and operations on vertex 0 should be invalid
        assertEquals("Empty graph should report 0 vertices", 0, grafo0.numVertices());
        expectThrows(IndexOutOfBoundsException.class, () -> grafo0.primeiroListaAdj(0));
        expectThrows(IndexOutOfBoundsException.class, () -> grafo0.existeAresta(0, 0));
    }

    @Test(timeout = 4000)
    public void test9() throws Throwable {
        // Given: a single-vertex graph with a self-loop of negative weight
        Grafo grafo0 = new Grafo(1);
        grafo0.insereAresta(0, 0, -93);

        // When: compute the transpose
        Grafo grafo1 = grafo0.grafoTransposto();

        // Then: transpose should preserve vertex count and the self-loop should still be present
        assertNotNull("Transpose should not be null", grafo1);
        assertEquals("Transpose should preserve vertex count", grafo0.numVertices(), grafo1.numVertices());
        assertTrue("Transpose of self-loop should still contain the self-loop", grafo1.existeAresta(0, 0));
        // ensure original graph still contains the self-loop too
        assertTrue("Original graph should still contain the self-loop", grafo0.existeAresta(0, 0));
    }
}